        T.q('rb', [a[0] + nx*0.05, 0.4, a[1] + nz*0.05], [b[0] + nx*0.05, 0.4, b[1] + nz*0.05], [b[0] + nx*0.05, 3.2, b[1] + nz*0.05], [a[0] + nx*0.05, 3.2, a[1] + nz*0.05]);
